  "valuation.footnote": "የወጪ ዋጋ የእያንዳንዱን ምርት ወቅታዊ የአንድ ክፍል ወጪ ይጠቀማል፣ ስለዚህ በአዲስ ዋጋ መቀበል ሙሉውን መደርደሪያ እንደገና ይገመግማል። የተያዙ ክፍሎች እዚህ አሁንም ይቆጠራሉ — በእጅ ላይ ናቸው፣ ለትዕዛዝ ቃል የተገቡ ብቻ ናቸው። የጠፋ ገንዘብ በጭራሽ እንደ ዜሮ አይቆጠርም፤ አሃዙ እስኪታወቅ ድረስ መስክ ባዶ ይተዉት።",
