  "settings.delete.dialogDescription": "ይህ የመለያ መሰረዝ ግምገማ ይጠይቃል። መግቢያዎን ወይም ክምችትዎን ወዲያውኑ አያስወግድም፣ እናም ማንኛውንም የStripe ደንበኝነት ምዝገባ አይሰርዝም። ጥያቄውን ለማቅረብ እንደሚፈልጉ ለማረጋገጥ DELETE ይተይቡ።",
