  "printLib.usbUnavailable": "ከድረ-ገጽ የUSB ማተም Android Chrome እና የUSB OTG ገመድ ይፈልጋል። በዴስክቶፕ ላይ፤ አታሚውን ወደ ኮምፒዩተሩ ይሰኩና የPrint ቁልፍን ይጠቀሙ — በተጫነው አታሚ በኩል ያትማል። አይፎኖች በቀጥታ በUSB ማተም አይችሉም — በWi-Fi ከAirPrint ጋር ይጠቀሙ፤ ወይም ከሞባይል መተግበሪያ Bluetooth ይጠቀሙ (ከሞባይል መተግበሪያ ጋር ይመጣል)።",
